mapper.select:
SELECT refs.tenant_id, refs.agent_id, refs.agent_code FROM ( SELECT agent.tenant_id, agent.id AS agent_id, agent.agent_code FROM ai_agent agent WHERE agent.model_id = #{modelId} AND agent.deleted = 0
AND agent.tenant_id = #{tenantId}
UNION SELECT agent.tenant_id, agent.id AS agent_id, agent.agent_code FROM ai_agent_backup_model backup INNER JOIN ai_agent agent ON agent.id = backup.agent_id AND agent.tenant_id = backup.tenant_id AND agent.deleted = 0 WHERE backup.model_id = #{modelId}
AND agent.tenant_id = #{tenantId}
UNION SELECT agent.tenant_id, agent.id AS agent_id, agent.agent_code FROM ai_model_route_rule route_rule INNER JOIN ai_model_route_policy_version route_version ON route_version.id = route_rule.policy_version_id AND route_version.tenant_id = route_rule.tenant_id AND route_version.status = 'ACTIVE' INNER JOIN ai_model_route_policy route_policy ON route_policy.id = route_version.policy_id AND route_policy.tenant_id = route_version.tenant_id AND route_policy.current_version_id = route_version.id AND route_policy.status = 'ACTIVE' AND route_policy.deleted = 0 INNER JOIN ai_agent agent ON agent.model_route_policy_id = route_policy.id AND agent.tenant_id = route_policy.tenant_id AND agent.deleted = 0 WHERE route_rule.deployment_id = #{modelId}
AND route_rule.tenant_id = #{tenantId} AND agent.tenant_id = #{tenantId}
UNION SELECT agent.tenant_id, agent.id AS agent_id, agent.agent_code FROM ai_model_experiment experiment INNER JOIN ai_agent agent ON agent.id = experiment.agent_id AND agent.tenant_id = experiment.tenant_id AND agent.deleted = 0 LEFT JOIN ai_runtime_publish_task deactivation ON deactivation.id = experiment.deactivation_task_id AND deactivation.tenant_id = experiment.tenant_id AND deactivation.experiment_id = experiment.id AND deactivation.experiment_publish_action = 'DEACTIVATE' WHERE (experiment.control_deployment_id = #{modelId} OR experiment.treatment_deployment_id = #{modelId}) AND ( experiment.status IN ('DRAFT', 'RUNNING') OR ( experiment.status IN ('STOPPED', 'COMPLETED') AND (experiment.activation_task_id IS NOT NULL OR experiment.started_at IS NOT NULL) AND ( deactivation.id IS NULL OR deactivation.status <> 'APPLIED' OR deactivation.gate_status = 'BLOCKED' ) ) )
AND experiment.tenant_id = #{tenantId} AND agent.tenant_id = #{tenantId}
) refs ORDER BY refs.tenant_id, refs.agent_id
